def get_byte_string(obj):
    if isinstance(obj, str):  return obj.encode("utf-8")
    if isinstance(obj, dict): return json.dumps(obj, ensure_ascii=False).encode("utf-8")
    if isinstance(obj, list): return json.dumps(obj, ensure_ascii=False).encode("utf-8")
    return str(obj).encode("utf-8")


def now_str():
    """UTC-время в формате 'YYYY-MM-DD HH:MM:SS.mmm'."""
    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]


def now_ctl():
    """Время для ctl_validfrom в формате ISO 'YYYY-MM-DDTHH:MM:SS'."""
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S")


def make_test_sap(suffix: int) -> str:
    """Тестовый sb_sap_identification (табельный), например: 9000000042."""
    return f"{CONTACTS_TEST_SAP_PREFIX}{suffix:02d}"


def make_test_contact_name(suffix: int) -> str:
    """Тестовый contact_name (уникальный идентификатор), например: 'Тест Иванов И. И. (9000000042)'."""
    sap = make_test_sap(suffix)
    return f"{CONTACTS_TEST_PREFIX}Иванов И. И. ({sap})"


