def now_iso(shift_sec: int = 0) -> str:
    """UTC в ISO-8601, как ожидает SberESM."""
    from datetime import timedelta
    return (datetime.now(timezone.utc) + timedelta(seconds=shift_sec)).strftime("%Y-%m-%dT%H:%M:%SZ")


