def create_a2a_request_message(message: str, sender:str = CHANNEL_AGENT_NAME, context: dict = None):
  parts = []
  if context:
    parts.append(
      {
        "kind": "data",
        "data": {
          "type": "default_context",
          "value": json.dumps(context, ensure_ascii=False) if type(context)==dict else context,
        }
      }
    )
  parts.append(
    {
      "kind": "data",
      "data": {
        "type": "mpr",
        "value": json.dumps(message, ensure_ascii=False) if type(message)==dict else message
      },
    }
  )
  return get_byte_string(
    {
      "jsonrpc": "2.0",
      "id": str(uuid.uuid4()),
      "method": "message/send",
      "params": {
        "message": {
          "contextId": f"mpr#{str(uuid.uuid4())}>{sender}#{str(uuid.uuid4())}",
          "kind": "message",
          "role": "agent",
          "parts": parts,
          "messageId": str(uuid.uuid4())
        },
        "metadata": {},
      }
    }
  )

